package dao;

import util.DBConnection;
import java.sql.*;
import java.util.*;

public class OpportunityDAO {
    // Each String[]: [opportunity_id, title, company, type, description, eligibility, deadline, application_url, alumni_id, alumni_name]
    public List<String[]> getAllOpportunities(){return searchOpportunities("");}
    public List<String[]> searchOpportunities(String keyword){List<String[]> list=new ArrayList<>();String sql="SELECT o.opportunity_id,o.title,o.company,o.type,o.description,o.eligibility,o.deadline,o.application_url,o.alumni_id,u.name alumni_name FROM opportunities o JOIN users u ON u.user_id=o.alumni_id JOIN alumni_profiles a ON a.user_id=o.alumni_id WHERE u.status='ACTIVE' AND a.verification_status='VERIFIED' AND (o.title LIKE ? OR o.company LIKE ? OR o.type LIKE ? OR o.description LIKE ?) ORDER BY o.created_at DESC";String k="%"+(keyword==null?"":keyword.trim())+"%";try(Connection c=DBConnection.getConnection();PreparedStatement ps=c.prepareStatement(sql)){for(int i=1;i<=4;i++)ps.setString(i,k);try(ResultSet rs=ps.executeQuery()){while(rs.next())list.add(new String[]{rs.getString("opportunity_id"),rs.getString("title"),rs.getString("company"),rs.getString("type"),rs.getString("description"),rs.getString("eligibility"),String.valueOf(rs.getDate("deadline")),rs.getString("application_url"),rs.getString("alumni_id"),rs.getString("alumni_name")});}}catch(SQLException e){System.err.println("searchOpportunities: "+e.getMessage());}return list;}
    public boolean addOpportunity(int alumniId,String title,String company,String type,String description,String eligibility,java.sql.Date deadline,String applicationUrl){String sql="INSERT INTO opportunities(alumni_id,title,company,type,description,eligibility,deadline,application_url) SELECT ?,?,?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM alumni_profiles WHERE user_id=? AND verification_status='VERIFIED')";try(Connection c=DBConnection.getConnection();PreparedStatement ps=c.prepareStatement(sql)){ps.setInt(1,alumniId);ps.setString(2,title);ps.setString(3,company);ps.setString(4,type.toUpperCase());ps.setString(5,description);ps.setString(6,eligibility);ps.setDate(7,deadline);ps.setString(8,applicationUrl);ps.setInt(9,alumniId);return ps.executeUpdate()==1;}catch(SQLException e){System.err.println("addOpportunity: "+e.getMessage());return false;}}
    public boolean saveOpportunity(int studentId,int opportunityId){String sql="INSERT IGNORE INTO saved_opportunities(student_id,opportunity_id) VALUES(?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement ps=c.prepareStatement(sql)){ps.setInt(1,studentId);ps.setInt(2,opportunityId);return ps.executeUpdate()==1;}catch(SQLException e){System.err.println("saveOpportunity: "+e.getMessage());return false;}}
    public List<String[]> getSavedOpportunities(int studentId){List<String[]> list=new ArrayList<>();String sql="SELECT o.opportunity_id,o.title,o.company,o.type,o.deadline,o.application_url FROM saved_opportunities s JOIN opportunities o ON o.opportunity_id=s.opportunity_id WHERE s.student_id=? ORDER BY o.created_at DESC";try(Connection c=DBConnection.getConnection();PreparedStatement ps=c.prepareStatement(sql)){ps.setInt(1,studentId);try(ResultSet rs=ps.executeQuery()){while(rs.next())list.add(new String[]{rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),String.valueOf(rs.getDate(5)),rs.getString(6)});}}catch(SQLException e){System.err.println("getSavedOpportunities: "+e.getMessage());}return list;}
}
